import type{Metadata}from'next';import{notFound}from'next/navigation';import PageHero from'@/components/PageHero';import PromptCard from'@/components/PromptCard';import{collections}from'@/lib/collections';import{promptItems}from'@/lib/prompts';export function generateStaticParams(){return collections.map(c=>({slug:c.slug}))}export async function generateMetadata({params}:{params:Promise<{slug:string}>}):Promise<Metadata>{const{slug}=await params,c=collections.find(x=>x.slug===slug);return c?{title:c.title,description:c.desc}:{}}export default async function Collection({params}:{params:Promise<{slug:string}>}){const{slug}=await params,c=collections.find(x=>x.slug===slug);if(!c)notFound();const list=promptItems.filter(c.match);return <><PageHero eyebrow="FREE COMMERCIAL PROMPT SET" title={c.title+'.'} intro={c.desc}/><section className="library"><div className="collectionIntro"><h2>{list.length} editable prompt systems</h2><p>Professional production controls, editable variables and ready-to-copy output. No account is required.</p></div><div className="galleryGrid">{list.map(p=><PromptCard p={p} key={p.id}/>)}</div></section></>}
